public async Task<IActionResult> GetOrders(int customerId)
{
    var sql = $"SELECT * FROM Orders WHERE CustomerId = {customerId}";
    var orders = await _db.Orders.FromSqlRaw(sql).ToListAsync();
    return Ok(orders);
}

